setThing:
{
   if(target.type == "经验球" && this.useExpball(2000))
   {
      if(target.number > 1)
      {
         target.number -= 1;
         return false;
      }
      return true;
   }
   if(target.type == "药品" && target.hpVal > 0 && this.huanShou.life > 0)
   {
      this.body.life += target.hpVal;
      return true;
   }
   var _loc5_;
   if(target.type == "生命之源" && this.body.life > 0)
   {
      _loc5_ = this.body.maxLife - this.body.life;
      if(this.role.lifeSourse >= _loc5_)
      {
         this.role.lifeSourse -= _loc5_;
         this.body.life = this.body.maxLife;
      }
      else
      {
         this.body.life += this.role.lifeSourse;
         this.role.lifeSourse = 0;
      }
      return false;
   }
   var _loc4_;
   if(target.type == "电浆药水")
   {
      if(this.huanShou.life <= 0)
      {
         _global.sysMsg.addMsg("使用对像已经死亡，使用无效");
      }
      else if(this.huanShou.allFen < 3000)
      {
         _global.sysMsg.addMsg("极品30星以上的幻兽才使用");
      }
      else
      {
         if(this.huanShou.element != 5)
         {
            this.huanShou.element = 5;
            this.body.life += 0;
            _global.sysMsg.addMsg("幻兽" + this.huanShou.type + "使用了电浆药水，获得了雷元素属性");
            this.huanShou.checkUp();
            this.flashView();
            if(target.number > 1)
            {
               target.number -= 1;
               return false;
            }
            return true;
         }
         _global.sysMsg.addMsg("该幻兽已经拥有雷元素了，使用无效");
      }
   }
   else
   {
      if(target.type == "幻兽转世水晶")
      {
         this.huanShou.maxZs += 1;
         this.flashView();
         _global.sysMsg.addMsg("幻兽" + this.huanShou.type + "最大转世次数增加1次，最大转世次数" + this.huanShou.maxZs + "次");
         if(target.number > 1)
         {
            target.number -= 1;
            return false;
         }
         return true;
      }
      if(target.type == "幻兽转世丹")
      {
         _loc4_ = this.huanShou.maxZs - this.huanShou.zs;
         if(_loc4_ <= 0)
         {
            _global.sysMsg.addMsg("主幻兽的转世次数已经达到极限，不能再进行幻化了。");
            return false;
         }
         if(_loc4_ > 10)
         {
            _loc4_ = 10;
         }
         this.huanShou.zs += _loc4_;
         this.huanShou.checkUp();
         this.flashView();
         _global.sysMsg.addMsg("幻兽" + this.huanShou.type + "转世次数增加" + _loc4_ + "次。");
         if(target.number > 1)
         {
            target.number -= 1;
            return false;
         }
         return true;
      }
      if(target.type == "神兽药水")
      {
         if(this.huanShou.sd >= this.huanShou.sds[this.huanShou.nowLifeLv])
         {
            _global.sysMsg.addMsg("幻兽" + this.huanShou.type + "已经使用了" + this.huanShou.sd + "个神兽药水，不能再使用。");
            return false;
         }
         this.huanShou.sd++;
         this.huanShou.rareFen += 500;
         _global.sysMsg.addMsg("幻兽" + this.huanShou.type + "使用了神兽药水，罕见度增加。");
         this.huanShou.checkUp();
         this.flashView();
         this.body.life += 0;
         if(target.number > 1)
         {
            target.number -= 1;
            return false;
         }
         return true;
      }
      if(target.type == "奇异果")
      {
         if(this.huanShou.qyg >= this.huanShou.qygs[this.huanShou.nowLifeLv])
         {
            _global.sysMsg.addMsg("幻兽" + this.huanShou.type + "已经使用了" + this.huanShou.qyg + "个奇异果，不能再使用。");
            return false;
         }
         this.huanShou.qyg++;
         this.huanShou.rareFen += 50;
         _global.sysMsg.addMsg("幻兽" + this.huanShou.type + "使用了奇异果，罕见度增加。");
         this.huanShou.checkUp();
         this.flashView();
         this.body.life += 0;
         if(target.number > 1)
         {
            target.number -= 1;
            return false;
         }
         return true;
      }
      if(target.type == "风神兽内丹")
      {
         if(this.huanShou.isGod == true)
         {
            _global.sysMsg.addMsg("幻兽" + this.huanShou.type + "已经是神使幻兽，不能再使用神兽内丹了。");
            return false;
         }
         if(this.huanShou.maxMinAttackFen > 0)
         {
            _global.sysMsg.addMsg("幻兽" + this.huanShou.type + "的最小攻击成长率是主属性，不能使用风神兽内丹。");
            return false;
         }
         this.huanShou.isGod = true;
         this.huanShou.rareFen += 200;
         this.huanShou.rateMinAttack = Math.round(this.huanShou.rateMinAttack * (1.5 + Math.random() / 2) * 10000) / 10000;
         _global.sysMsg.addMsg("幻兽" + this.huanShou.type + "使用神兽内丹，蜕变成神使幻兽。");
         this.huanShou.checkUp();
         this.flashView();
         this.body.life += 0;
         if(target.number > 1)
         {
            target.number -= 1;
            return false;
         }
         return true;
      }
      if(target.type == "火神兽内丹")
      {
         if(this.huanShou.isGod == true)
         {
            _global.sysMsg.addMsg("幻兽" + this.huanShou.type + "已经是神使幻兽，不能再使用神兽内丹了。");
            return false;
         }
         if(this.huanShou.maxMaxAttackFen > 0)
         {
            _global.sysMsg.addMsg("幻兽" + this.huanShou.type + "的最大攻击成长率是主属性，不能使用火神兽内丹。");
            return false;
         }
         this.huanShou.isGod = true;
         this.huanShou.rareFen += 200;
         this.huanShou.rateMaxAttack = Math.round(this.huanShou.rateMaxAttack * (1.5 + Math.random() / 2) * 10000) / 10000;
         _global.sysMsg.addMsg("幻兽" + this.huanShou.type + "使用神兽内丹，蜕变成神使幻兽。");
         this.huanShou.checkUp();
         this.flashView();
         this.body.life += 0;
         if(target.number > 1)
         {
            target.number -= 1;
            return false;
         }
         return true;
      }
      if(target.type == "水神兽内丹")
      {
         if(this.huanShou.isGod == true)
         {
            _global.sysMsg.addMsg("幻兽" + this.huanShou.type + "已经是神使幻兽，不能再使用神兽内丹了。");
            return false;
         }
         if(this.huanShou.maxLifeFen > 0)
         {
            _global.sysMsg.addMsg("幻兽" + this.huanShou.type + "的生命成长率是主属性，不能使用水神兽内丹。");
            return false;
         }
         this.huanShou.isGod = true;
         this.huanShou.rareFen += 200;
         this.huanShou.rateLife = Math.round(this.huanShou.rateLife * (1.5 + Math.random() / 2) * 10000) / 10000;
         _global.sysMsg.addMsg("幻兽" + this.huanShou.type + "使用神兽内丹，蜕变成神使幻兽。");
         this.huanShou.checkUp();
         this.flashView();
         this.body.life += 0;
         if(target.number > 1)
         {
            target.number -= 1;
            return false;
         }
         return true;
      }
      if(target.type == "地神兽内丹")
      {
         if(this.huanShou.isGod == true)
         {
            _global.sysMsg.addMsg("幻兽" + this.huanShou.type + "已经是神使幻兽，不能再使用神兽内丹了。");
            return false;
         }
         if(this.huanShou.maxDefenseFen > 0)
         {
            _global.sysMsg.addMsg("幻兽" + this.huanShou.type + "的防御成长率是主属性，不能使用地神兽内丹。");
            return false;
         }
         this.huanShou.isGod = true;
         this.huanShou.rareFen += 200;
         this.huanShou.rateDefense = Math.round(this.huanShou.rateDefense * (1.5 + Math.random() / 2) * 10000) / 10000;
         _global.sysMsg.addMsg("幻兽" + this.huanShou.type + "使用神兽内丹，蜕变成神使幻兽。");
         this.huanShou.checkUp();
         this.flashView();
         this.body.life += 0;
         if(target.number > 1)
         {
            target.number -= 1;
            return false;
         }
         return true;
      }
      if(target.type == "雷神兽内丹")
      {
         if(this.huanShou.lifeLvUp() == false)
         {
            return false;
         }
         _global.sysMsg.addMsg("幻兽" + this.huanShou.type + "使用神秘的雷神兽内丹，进化出第" + this.huanShou.lifeLv + "幻兽。");
         this.huanShou.checkUp();
         this.flashView();
         this.body.life += 0;
         if(target.number > 1)
         {
            target.number -= 1;
            return false;
         }
         return true;
      }
   }
   return false;
}

lifeLvUp:
{
      if(this.mainFen < 6000 && this.type != "奇迹龙")
      {
         _global.sysMsg.addMsg("该幻兽没不符合要求条件。");
         return false;
      }
      if(this.nowLifeLv >= 2)
      {
         _global.sysMsg.addMsg("该幻兽已经进化到第三代了，无法继续进化了！！！");
         return false;
      }
      this.nowLifeLv += 1;
      var _loc3_ = 1000;
      if(this.maxLifeFen > 0)
      {
         this.maxRateLife *= this.nextLvMain;
         this.rateLife *= this.nextLvMain;
         this.maxLifeFen += _loc3_;
      }
      else
      {
         this.rateLife *= this.nextLvRate;
      }
      if(this.maxMinAttackFen > 0)
      {
         this.maxRateMinAttack *= this.nextLvMain;
         this.rateMinAttack *= this.nextLvMain;
         this.maxMinAttackFen += _loc3_;
      }
      else
      {
         this.rateMinAttack *= this.nextLvRate;
      }
      if(this.maxMaxAttackFen > 0)
      {
         this.maxRateMaxAttack *= this.nextLvMain;
         this.rateMaxAttack *= this.nextLvMain;
         this.maxMaxAttackFen += _loc3_;
      }
      else
      {
         this.rateMaxAttack *= this.nextLvRate;
      }
      if(this.maxDefenseFen > 0)
      {
         this.maxRateDefense *= this.nextLvMain;
         this.rateDefense *= this.nextLvMain;
         this.maxDefenseFen += _loc3_;
      }
      else
      {
         this.rateDefense *= this.nextLvRate;
      }
      this.turned();
      this.maxZs += 50;
      this.rareFen += 500;
      return true;
   }

turned:
{
      if(this.zs < this.maxZs)
      {
         this.zs += 1;
      }
      if(this.oldLevels < this.levels)
      {
         this.oldLevels = this.levels;
         this.oldNowExp = this.nowExp;
         this.oldMaxExp = this.maxExp;
      }
      this.levels = 1;
      this.nowExp = 0;
      this.maxExp = Math.floor(this.levels * 9);
   }
